const config = window.PLAYER_CONFIG || {};
const stream = new Audio();
stream.preload = "none";

let datosHistorial = [];

// --- 1. FUNCIÓN DE METADATOS (WILCAM) ---
async function updateMetadata() {
    try {
        const response = await fetch(`${config.api_url}&nocache=${Date.now()}`);
        const data = await response.json();
        
        if (!data) return;

        let rawTitle = data.title || "Tiempo Final Medios";
        let artista = "Tiempo Final Medios";
        let cancion = "En Vivo";

        if (rawTitle.includes("-")) {
            const partes = rawTitle.split("-");
            artista = partes[0].trim();
            cancion = partes[1].trim();
        }

        // Actualizar UI Principal y Mini
        const elementos = {
            "track-artist": artista,
            "track-title": cancion,
            "mini-artist": artista,
            "mini-song": cancion
        };

        for (let id in elementos) {
            const el = document.getElementById(id);
            if (el) el.textContent = elementos[id];
        }

        const portadaUrl = data.art || "images/375469576_893356532265722_6679973870328184336_n.JPG";
        if (document.getElementById("cover-main")) document.getElementById("cover-main").src = portadaUrl;
        if (document.getElementById("cover-mini")) document.getElementById("cover-mini").src = portadaUrl;
        
        const fondo = document.getElementById("bg-blur");
        if (fondo) fondo.style.backgroundImage = `url('${portadaUrl}')`;

        // Procesar Historial (Lista de strings en Wilcam)
        if (data.history && Array.isArray(data.history)) {
            datosHistorial = data.history;
            renderizarHistorial(datosHistorial);
        }

    } catch (error) {
        console.error("Error API:", error);
    }
}

// --- 2. RENDERIZAR HISTORIAL (LIMPIEZA DE TEXTO) ---
function renderizarHistorial(lista) {
    const contenedor = document.getElementById("history-list");
    if (!contenedor) return;
    contenedor.innerHTML = ""; 

    lista.forEach(item => {
        if (!item || typeof item !== 'string') return;
        
        // Limpiar "1.) " y "<br>"
        let textoLimpio = item.replace(/^\d+\.\)\s*/, "").replace(/<br\s*\/?>/gi, "").trim();
        let hArtista = "InsideFM", hCancion = textoLimpio;
        
        if (textoLimpio.includes("-")) {
            const p = textoLimpio.split("-");
            hArtista = p[0].trim(); hCancion = p[1].trim();
        }

        const div = document.createElement("div");
        div.className = "history-item";
        div.innerHTML = `
            <img src="images/ChatGPT_Image_23_ago_2026__09_41_45_p.m-removebg-preview - copia - copia (22).png" onerror="this.src='https://imgur.com/a/51Y7c3A'" alt="Portada">
            <div class="history-meta">
                <div class="history-title">${hCancion}</div>
                <div class="history-artist">${hArtista}</div>
            </div>`;
        contenedor.appendChild(div);
    });
}

// --- 3. LÓGICA DE TEMA (CLARO/OSCURO) - CORREGIDO ---
function toggleTheme() {
    const body = document.body;
    // IMPORTANTE: Tu CSS usa "body.light", no "light-theme"
    const isLight = body.classList.toggle("light"); 
    localStorage.setItem("theme", isLight ? "light" : "dark");
    actualizarIconoTema(isLight);
}

function actualizarIconoTema(isLight) {
    const iconSun = document.getElementById("icon-sun");
    const iconMoon = document.getElementById("icon-moon");
    if (iconSun && iconMoon) {
        if (isLight) {
            iconSun.style.display = "none";
            iconMoon.style.display = "block";
        } else {
            iconSun.style.display = "block";
            iconMoon.style.display = "none";
        }
    }
}

// --- 4. INICIALIZACIÓN Y EVENTOS ---
document.addEventListener("DOMContentLoaded", () => {
    // 1. Cargar Tema guardado
    const savedTheme = localStorage.getItem("theme");
    if (savedTheme === "light") {
        document.body.classList.add("light");
        actualizarIconoTema(true);
    }

    // 2. Evento Botón Tema
    const btnTheme = document.getElementById("btn-theme");
    if (btnTheme) btnTheme.onclick = toggleTheme;

    // 3. Eventos Historial
    const btnHistorial = document.getElementById("btn-history");
    const panelHistorial = document.getElementById("history-panel");
    const capaHistorial = document.getElementById("history-overlay");
    const cerrarHistorial = document.getElementById("history-close");

    if (btnHistorial) {
        btnHistorial.onclick = () => {
            renderizarHistorial(datosHistorial); 
            panelHistorial.classList.add("open");
            capaHistorial.classList.add("open");
        };
    }

    const cerrarPanel = () => {
        if(panelHistorial) panelHistorial.classList.remove("open");
        if(capaHistorial) capaHistorial.classList.remove("open");
    };

    if (cerrarHistorial) cerrarHistorial.onclick = cerrarPanel;
    if (capaHistorial) capaHistorial.onclick = cerrarPanel;

    // 4. Iniciar Reloj y Metadata
    actualizarReloj();
    updateMetadata();
    setInterval(actualizarReloj, 1000);
    setInterval(updateMetadata, 20000);
});

// --- 5. FUNCIONES DE APOYO (RELOJ, PLAY, VOL) ---
function actualizarReloj() {
    const ahora = new Date();
    const elFecha = document.getElementById("clock-date");
    const elHora = document.getElementById("clock-time");
    if (elFecha) {
        const opciones = { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' };
        let f = ahora.toLocaleDateString('es-ES', opciones);
        elFecha.textContent = f.charAt(0).toUpperCase() + f.slice(1);
    }
    if (elHora) elHora.textContent = ahora.toLocaleTimeString('es-ES');
}

const btnPlay = document.getElementById("btn-play");
const iconoPlay = document.getElementById("icon-play");
const iconoPause = document.getElementById("icon-pause");

if (btnPlay) {
    btnPlay.onclick = () => {
        if (stream.paused) {
            stream.src = config.stream_url;
            stream.play().catch(e => console.error("Error audio:", e));
            if(iconoPlay) iconoPlay.style.display = "none";
            if(iconoPause) iconoPause.style.display = "block";
            document.querySelectorAll(".wave1, .wave2").forEach(w => w.classList.add("playing"));
        } else {
            stream.pause();
            stream.src = "";
            if(iconoPlay) iconoPlay.style.display = "block";
            if(iconoPause) iconoPause.style.display = "none";
            document.querySelectorAll(".wave1, .wave2").forEach(w => w.classList.remove("playing"));
        }
    };
}

const sliderVol = document.getElementById("volume-slider");
if (sliderVol) {
    sliderVol.oninput = (e) => {
        stream.volume = e.target.value / 100;
        const volPct = document.getElementById("vol-pct");
        if(volPct) volPct.textContent = e.target.value + "%";
    };
}